function PISANO_NAIVE(m):
    if m == 1: return 1
    (a, b) <- (0, 1)                      # the seed Q^0(0,1)
    for k = 1, 2, 3, ... up to 6m:
        (a, b) <- (b mod m, (a + b) mod m)   # apply the shift Q
        if a == 0 and b == 1:            # orbit returned to the seed
            return k                     # k = order(Q) = pi(m)
    error "unreachable"

