from math import gcd
from typing import Tuple

def pisano_period_naive(m: int) -> int:
    """Pisano period pi(m) as the order of the Fibonacci shift Q(a,b)=(b,a+b):
    the least k>0 returning the orbit of (0,1) to (0,1). O(pi(m)) ops."""
    if m == 1:
        return 1
    a, b = 0, 1
    for k in range(1, 6 * m + 1):
        a, b = b % m, (a + b) % m
        if a == 0 and b == 1:
            return k
    raise RuntimeError("unreachable: pi(m) <= 6m for all m")

algorithms.pseudocode:
function FIB_PAIR_MOD(k, m):           # (F_k, F_{k+1}) mod m, O(log k)
    if k == 0: return (0 mod m, 1 mod m)
    (a, b) <- FIB_PAIR_MOD(floor(k/2), m)
    c <- a * (2b - a) mod m                 # F_{2i}
    d <- a*a + b*b mod m                     # F_{2i+1}
    if k odd: return (d, (c + d) mod m)
    else:     return (c, d)

function SHIFT_POW_APPLY(a, b, k, m):        # Q^k (a,b) mod m
    (fk, fk1) <- FIB_PAIR_MOD(k, m)
    return ( a*(fk1 - fk) + b*fk  mod m,
             a*fk        + b*fk1  mod m )

