from typing import Tuple

def fib_pair_mod(k: int, m: int) -> Tuple[int, int]:
    """Return (F_k mod m, F_{k+1} mod m) via fast doubling = fast powering of
    the Fibonacci matrix Q. O(log k) ring operations."""
    def fd(n: int) -> Tuple[int, int]:
        if n == 0:
            return (0 % m, 1 % m)
        a, b = fd(n >> 1)
        c = (a * ((2 * b - a) % m)) % m      # F_{2i}
        d = (a * a + b * b) % m              # F_{2i+1}
        return (d, (c + d) % m) if (n & 1) else (c, d)
    return fd(k)

def shift_pow_apply(a: int, b: int, k: int, m: int) -> Tuple[int, int]:
    """Closed form Q^k(a,b) = (a(F_{k+1}-F_k)+b F_k, a F_k + b F_{k+1})."""
    fk, fk1 = fib_pair_mod(k, m)
    first = (a * ((fk1 - fk) % m) + b * fk) % m
    second = (a * fk + b * fk1) % m
    return (first, second)

from math import gcd
from typing import Dict

def lcm(x: int, y: int) -> int:
    return x // gcd(x, y) * y

def factorize(m: int) -> Dict[int, int]:
    f: Dict[int, int] = {}
    d, n = 2, m
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f

def pisano_period_factored(m: int, prime_power_period) -> int:
    """pi(m) = lcm over prime powers p^e || m of pi(p^e)   (Corollary 5.2).
    `prime_power_period(q)` returns pi(q) for a prime power q."""
    if m == 1:
        return 1
    result = 1
    for p, e in factorize(m).items():
        result = lcm(result, prime_power_period(p ** e))
    return result

from typing import Tuple, List

def fib_pair_mod(k: int, m: int) -> Tuple[int, int]:
    def fd(n: int) -> Tuple[int, int]:
        if n == 0:
            return (0 % m, 1 % m)
        a, b = fd(n >> 1)
        c = (a * ((2 * b - a) % m)) % m
        d = (a * a + b * b) % m
        return (d, (c + d) % m) if (n & 1) else (c, d)
    return fd(k)

def prime_factors(n: int) -> List[int]:
    ps, d = [], 2
    while d * d <= n:
        if n % d == 0:
            ps.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        ps.append(n)
    return ps

def verify_pisano_period(m: int, P: int) -> bool:
    """Certify that P == pi(m) using the period-return duality (Thm 3.3):
    (i) P is an apparition-return: F_P = 0 and F_{P+1} = 1 (mod m);
    (ii) minimality: for every prime q | P, P/q fails the same test.
    O(omega(P) * log P) ring operations via fast doubling."""
    fk, fk1 = fib_pair_mod(P, m)
    if not (fk == 0 % m and fk1 == 1 % m):
        return False                       # P is not even a multiple of pi(m)
    for q in prime_factors(P):
        gk, gk1 = fib_pair_mod(P // q, m)
        if gk == 0 % m and gk1 == 1 % m:
            return False                   # P/q already works -> P not minimal
    return True
